mapper.select:
select sch_id as schId, sch_name as schName, IS_DEFAULT as isDefault from BOK_SCHEME_INFO where scheme_type = '02'
AND ( SCH_ID like concat_ws('','%',#{searchKey},'%') OR SCH_NAME like concat_ws('','%',#{searchKey},'%') )
AND ( SCH_ID like concat_ws('','%',#{search},'%') OR SCH_NAME like concat_ws('','%',#{search},'%') )
AND (SCH_ID = #{schId} OR SCH_NAME = #{schName} )
AND SCH_NAME = #{schName}
AND SCH_ID != #{owner}

select t.seq_no as seqNo, t.sch_id as schId, b.IS_DEFAULT as isDefault , t.asset_classify as assetClassify, t.asset_classify as assetClassifyCode, t.capi_income_feature as capiIncomeFeature, t.capi_income_feature as capiIncomeFeatureCode, t.income_type as incomeType, t.income_type as incomeTypeCode, t.taxable_sign as taxableSign, t.taxable_sign as taxableSignCode, t.fee_type as feeType, t.fee_type as feeTypeCode, t.tax_rate*100 as taxRate, DATE_FORMAT(t.eff_date, '%Y-%m-%d') as effDate from TAX_VAT_SCHEDULE t left join BOK_SCHEME_INFO b on t.SCH_ID=b.SCH_ID
AND t.seq_no in
#{item}
AND t.SCH_ID = #{schId}
AND t.asset_classify in
#{item}
AND t.capi_income_feature in
#{item}
AND t.income_type in
#{item}
AND t.fee_type in
#{item}
and t.eff_date >= STR_TO_DATE(#{effDateBegin},'%Y-%m-%d')
and t.eff_date <= STR_TO_DATE(#{effDateEnd},'%Y-%m-%d')
and t.eff_date = STR_TO_DATE(#{effDate},'%Y-%m-%d')
AND t.seq_no != #{owner}

select t.tax_id as taxId, t.sch_id as schId, b.IS_DEFAULT as isDefault , t.add_tax_type as addTaxType, t.add_tax_type as addTaxTypeCode, t.tax_rate*100 as taxRate, DATE_FORMAT(t.eff_date, '%Y-%m-%d') as effDate from TAX_ADT_SCHEDULE t left join BOK_SCHEME_INFO b on t.SCH_ID=b.SCH_ID
AND t.tax_id in
#{item}
AND t.SCH_ID = #{schId}
AND t.add_tax_type in
#{item}
and t.eff_date >= STR_TO_DATE(#{effDateBegin},'%Y-%m-%d')
and t.eff_date <= STR_TO_DATE(#{effDateEnd},'%Y-%m-%d')
and t.eff_date = STR_TO_DATE(#{effDate},'%Y-%m-%d')
AND t.tax_id != #{owner}

select tti.seq_no as seqNo, tti.sch_id as schId, a.assetId as assetId, a.assetName as assetName, b.IS_DEFAULT as isDefault , tti.asset_classify as assetClassify, tti.asset_classify as assetClassifyCode, tti.capi_income_feature as capiIncomeFeature, tti.capi_income_feature as capiIncomeFeatureCode, tti.income_type as incomeType, tti.income_type as incomeTypeCode, tti.taxable_sign as taxableSign, tti.taxable_sign as taxableSignCode, tti.tax_rate*100 as taxRate, DATE_FORMAT(tti.eff_date, '%Y-%m-%d') as effDate, tti.maintenance_mode as maintenanceMode, tti.maintenance_mode as maintenanceModeCode, tti.fee_type as feeTypeCode, tti.fee_type as feeType from TAX_TAXABLE_INFO tti inner join (
select IFNULL(fp.finprod_market_id, fp.finprod_id) as assetId, IFNULL(fp.finprod_abbr, fp.finprod_name) as assetName, fp.finprod_id as originalFinprodId from fin_product_type fpt inner join fin_product fp on fp.finprod_id = fpt.finprod_id where fpt.type_3 is not null
union all
select ftp.finprod_id as assetId, ftp.finprod_id as assetName, ftp.finprod_id as originalFinprodId from fin_product_type fpt inner join fin_trade_product ftp on ftp.finprod_id = fpt.finprod_id where fpt.type_3 is not null and ftp.branch = '0'
) a on a.originalFinprodId = tti.asset_id left join BOK_SCHEME_INFO b on tti.SCH_ID=b.SCH_ID
AND tti.seq_no in
#{item}
AND tti.SCH_ID = #{schId}
AND tti.asset_classify in
#{item}
AND a.assetId in
#{item}
AND tti.capi_income_feature in
#{item}
AND tti.income_type in
#{item}
AND tti.taxable_sign in
#{item}
and tti.eff_date >= STR_TO_DATE(#{effDateBegin},'%Y-%m-%d')
and tti.eff_date <= STR_TO_DATE(#{effDateEnd},'%Y-%m-%d')
AND tti.maintenance_mode in
#{item}
and tti.eff_date = STR_TO_DATE(#{effDate},'%Y-%m-%d')
AND tti.seq_no != #{owner}

select tas.scheme_type_2 as schemeType2 , tas.scheme_type_2 as schemeType2Code , tas.config_id as configId , b.IS_DEFAULT as isDefault , tas.config_name as configName , tas.remark as remark , tas.dict_code as dictCode, val.scheme_id as schemeId , val.seq_id as seqId , val.config_value as configValue , val.config_value as configValueCode , DATE_FORMAT(val.eff_date, '%Y-%m-%d') as effDate from bok_scheme_config tas inner join bok_scheme_config_val val on tas.config_id = val.config_id left join BOK_SCHEME_INFO b on val.SCHEME_ID = b.SCH_ID
AND seq_id in
#{item}
AND tas.config_id in
#{item}
AND tas.scheme_type_2 in
#{item}
AND val.scheme_id in
#{item}
and val.eff_date >= STR_TO_DATE(#{effDateBegin},'%Y-%m-%d')
and val.eff_date <= STR_TO_DATE(#{effDateEnd},'%Y-%m-%d')
and val.eff_date = STR_TO_DATE(#{effDate},'%Y-%m-%d')
AND val.seq_id != #{owner}
